# ==============================================================================
# PTC transcript annotation
#
# Purpose:
#   Derive transcript-level positional and canonical NMD-rule annotations
#   for PTC-producing SNVs.
#
# This script is shared across:
#   - TOPMed
#   - gnomAD
#   - ClinVar
#   - GREGoR
#
# Prerequisites:
#   1. Dataset-specific extraction and SNV filtering
#   2. ANNOVAR ensGene annotation
#   3. Canonical transcript selection by 01_variant_annotation.R
#   4. GENCODE v26 transcript structure generated by
#      02_GENCODEv26_transcript_structure.R
#
# Input:
#   - canonical transcript-specific variant annotation
#   - gencode_v26_transcript_structure.rds
#
# Output:
#   - transcript- and PTC-annotated variant dataset
#
# No allele-specific expression or TOPMed-specific outcomes are calculated
# in this script.
# ==============================================================================


# ------------------------------------------------------------------------------
# 1. Required packages
# ------------------------------------------------------------------------------

library(dplyr)
library(stringr)


# ------------------------------------------------------------------------------
# 2. Configuration
# ------------------------------------------------------------------------------

CONFIG <- list(

    # Output of 02_GENCODEv26_transcript_structure.R
    transcript_structure_file =
        "/path/to/gencode_v26_transcript_structure.rds",

    # Dataset-specific output file
    output_file =
        "/path/to/PTC_annotated_variants.rds"
)


# ------------------------------------------------------------------------------
# 3. Add GENCODE v26 transcript structure
# ------------------------------------------------------------------------------

# `variant.anno.hiqual` is generated by 01_variant_annotation.R
# and contains the selected transcript in `txnames`.

transcript_structure <- readRDS(
    CONFIG$transcript_structure_file
)

variants <- variant.anno.hiqual %>%
    left_join(
        transcript_structure,
        by = "txnames"
    ) %>%
    filter(
        !is.na(cds_exons)
    )

message(
    "Variants with GENCODE v26 transcript structure: ",
    nrow(variants)
)


# ------------------------------------------------------------------------------
# 4. Parse coding position from ANNOVAR transcript annotation
# ------------------------------------------------------------------------------

extract_coding_position <- function(
    annotation,
    transcript_id
) {

    fields <- strsplit(
        annotation,
        ":"
    )[[1]]

    transcript_index <- grep(
        pattern = transcript_id,
        x = fields,
        fixed = TRUE
    )

    if (length(transcript_index) == 0) {
        return(NA_real_)
    }

    coding_field <- fields[
        transcript_index[1] + 2
    ]

    if (!grepl("c\\.", coding_field)) {
        return(NA_real_)
    }

    coding_field <- strsplit(
        coding_field,
        "_"
    )[[1]][1]

    as.numeric(
        gsub(
            "\\D",
            "",
            coding_field
        )
    )
}

variants$coding.pos <- mapply(
    extract_coding_position,
    variants$V3,
    variants$txnames
)


# ------------------------------------------------------------------------------
# 5. Gene identifier
# ------------------------------------------------------------------------------

variants$GENE_ID <- vapply(
    strsplit(
        variants$V3,
        ":"
    ),
    `[`,
    character(1),
    1
)


# ------------------------------------------------------------------------------
# 6. Mutated coding exon
# ------------------------------------------------------------------------------

get_mutated_exon <- function(
    coding_pos,
    cds_exons
) {

    if (
        is.na(coding_pos) ||
        is.na(cds_exons)
    ) {
        return(NA_real_)
    }

    exon_ends <- as.numeric(
        strsplit(
            as.character(cds_exons),
            ","
        )[[1]]
    )

    hit <- which(
        coding_pos <= exon_ends
    )

    if (length(hit) == 0) {
        return(NA_real_)
    }

    hit[1]
}

variants$mut.exon <- mapply(
    get_mutated_exon,
    variants$coding.pos,
    variants$cds_exons
)


# ------------------------------------------------------------------------------
# 7. Mutated exon length
# ------------------------------------------------------------------------------

get_exon_length <- function(
    mutated_exon,
    cds_exons
) {

    if (
        is.na(mutated_exon) ||
        is.na(cds_exons)
    ) {
        return(NA_real_)
    }

    exon_ends <- as.numeric(
        strsplit(
            as.character(cds_exons),
            ","
        )[[1]]
    )

    if (mutated_exon == 1) {
        return(exon_ends[1])
    }

    exon_ends[mutated_exon] -
        exon_ends[mutated_exon - 1]
}

variants$length.mutated.exon <- mapply(
    get_exon_length,
    variants$mut.exon,
    variants$cds_exons
)


# ------------------------------------------------------------------------------
# 8. Start-proximal and exon-length features
# ------------------------------------------------------------------------------

variants <- variants %>%
    mutate(

        first.100 = case_when(
            is.na(coding.pos) ~ NA_character_,
            coding.pos <= 100 ~ "first 100",
            TRUE ~ "not first 100"
        ),

        first.200 = case_when(
            is.na(coding.pos) ~ NA_character_,
            coding.pos <= 200 ~ "first 200",
            TRUE ~ "not first 200"
        ),

        long.exon = case_when(
            is.na(length.mutated.exon) ~ NA_character_,
            length.mutated.exon >= 400 ~ "long.exon",
            TRUE ~ "not long.exon"
        )
    )


# ------------------------------------------------------------------------------
# 9. PTC geometry
# ------------------------------------------------------------------------------

get_ptc_to_ejc <- function(
    coding_pos,
    mutated_exon,
    cds_exons
) {

    if (
        is.na(coding_pos) ||
        is.na(mutated_exon) ||
        is.na(cds_exons)
    ) {
        return(NA_real_)
    }

    exon_ends <- as.numeric(
        strsplit(
            as.character(cds_exons),
            ","
        )[[1]]
    )

    exon_ends[mutated_exon] -
        coding_pos
}

variants$PTC.2.EJC <- mapply(
    get_ptc_to_ejc,
    variants$coding.pos,
    variants$mut.exon,
    variants$cds_exons
)

variants <- variants %>%
    mutate(
        PTC.2.start = coding.pos,
        PTC.2.end = cds_length - coding.pos
    )


# ------------------------------------------------------------------------------
# 10. Last-exon rule
# ------------------------------------------------------------------------------

variants <- variants %>%
    mutate(
        last.exon = case_when(

            is.na(exon_count) |
                is.na(mut.exon) ~
                NA_character_,

            exon_count == 1 ~
                NA_character_,

            exon_count == mut.exon ~
                "lastexon",

            TRUE ~
                "notlastexon"
        )
    )


# ------------------------------------------------------------------------------
# 11. Penultimate-last-50-bp rule
# ------------------------------------------------------------------------------

get_penultimate_last50 <- function(
    coding_pos,
    mutated_exon,
    exon_count,
    cds_exons
) {

    if (
        is.na(coding_pos) ||
        is.na(mutated_exon) ||
        is.na(exon_count) ||
        is.na(cds_exons)
    ) {
        return(NA_character_)
    }

    if (exon_count == 1) {
        return(
            "not penultimate.last50bp"
        )
    }

    if (
        exon_count !=
        mutated_exon + 1
    ) {
        return(
            "not penultimate.last50bp"
        )
    }

    exon_ends <- as.numeric(
        strsplit(
            as.character(cds_exons),
            ","
        )[[1]]
    )

    penultimate_end <-
        exon_ends[
            length(exon_ends) - 1
        ]

    penultimate_start <-
        if (length(exon_ends) > 2) {
            exon_ends[
                length(exon_ends) - 2
            ]
        } else {
            0
        }

    penultimate_length <-
        penultimate_end -
        penultimate_start

    fifty_position <-
        penultimate_end - 50

    if (
        coding_pos >= fifty_position &&
        coding_pos <= penultimate_end &&
        penultimate_length >= 50
    ) {
        return(
            "penultimate.last50bp"
        )
    }

    "not penultimate.last50bp"
}

variants$penultimate.last50bp <- mapply(
    get_penultimate_last50,
    variants$coding.pos,
    variants$mut.exon,
    variants$exon_count,
    variants$cds_exons
)


# ------------------------------------------------------------------------------
# 12. Full penultimate-exon indicator
# ------------------------------------------------------------------------------

variants <- variants %>%
    mutate(
        penultimate.full = case_when(

            is.na(exon_count) |
                is.na(mut.exon) ~
                NA_character_,

            exon_count > 1 &
                exon_count == mut.exon + 1 ~
                "penultimate",

            TRUE ~
                "not penultimate"
        )
    )


# ------------------------------------------------------------------------------
# 13. Multi-exon status
# ------------------------------------------------------------------------------

variants <- variants %>%
    mutate(
        multi_exon = exon_count > 1
    )


# ------------------------------------------------------------------------------
# 14. Save shared annotated dataset
# ------------------------------------------------------------------------------

variants_annotated <- variants

saveRDS(
    variants_annotated,
    CONFIG$output_file
)

message(
    "PTC annotation complete."
)

message(
    "Annotated variants: ",
    nrow(variants_annotated)
)
